mapper.select:
SELECT * FROM TBL_MONITORING

    DELETE_FLAG = 0

        AND MONITOR_TYPE = #{monitorType}


        AND ALERT_LEVEL = #{alertLevel}


        AND ORG_ID = #{orgId}


        AND MONITOR_TIME >= #{beginTime}


        AND MONITOR_TIME <= #{endTime}


ORDER BY MONITOR_TIME DESC

    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM TBL_MONITORING

    DELETE_FLAG = 0

        AND MONITOR_TYPE = #{monitorType}


        AND ALERT_LEVEL = #{alertLevel}


        AND ORG_ID = #{orgId}


        AND MONITOR_TIME >= #{beginTime}


        AND MONITOR_TIME <= #{endTime}

SELECT DATE_FORMAT(MONITOR_TIME, '%Y-%m-%d %H:00:00') AS timePoint, SUM(COALESCE(TRANSACTION_COUNT, 0)) AS transactionCount, SUM(COALESCE(SUCCESS_COUNT, 0)) AS successCount, SUM(COALESCE(FAILED_COUNT, 0)) AS failedCount, COALESCE(AVG(AVG_PROCESSING_TIME), 0) AS avgProcessingTime FROM TBL_MONITORING WHERE DELETE_FLAG = 0
AND ORG_ID = #{orgId}
AND MONITOR_TIME >= #{beginTime}
AND MONITOR_TIME <= #{endTime}
GROUP BY DATE_FORMAT(MONITOR_TIME, '%Y-%m-%d %H:00:00') ORDER BY timePoint ASC
